// Where the sea is: one bit per 8x8 pixel cell of the zoom-5
// chart, 1 for water. Built by tools/build-seamask.mjs from the tiles
// under map/ -- rerun it when those change. 652223 of 1048576 cells
// are water, which is the ocean this app is about.
//
// A cell is 128 world units across; chart position
// divided by that is the cell it falls in.

export const SEA_ZOOM = 5;
export const SEA_CELL = 128;
export const SEA_SIDE = 1024;
export const SEA_BITS = '';
